/**
 * Resolve a namespaced image key used by the catalogue:
 *   'product:dome'   → media.products.dome
 *   'scene:business' → solutions/projects photography
 * Keeps data files free of object paths and makes bad keys obvious in review.
 */
export function getImage(key) {
  if (!key) return null
  const [scope, name] = key.includes(':') ? key.split(':') : ['product', key]
  if (scope === 'scene') {
    return media.scenes[name] ?? media.solutions[name] ?? media.projects[name] ?? null
  }
  if (scope === 'product') return media.products[name] ?? null
  if (scope === 'hero') return media.hero
  return null
}

export default media
